const form=document.querySelector('#sign-in-form'),status=document.querySelector('#sign-in-status'),button=form.querySelector('[type="submit"]');
const requested=new URLSearchParams(location.search).get('next');let next='/training';
try{const target=new URL(requested||next,location.origin);if(target.origin===location.origin&&['/','/training','/journal','/account','/app.html'].includes(target.pathname))next=target.pathname+target.search;}catch{}
document.querySelector('#show-password').addEventListener('click',event=>{const show=form.elements.password.type==='password';form.elements.password.type=show?'text':'password';event.currentTarget.textContent=show?'Hide':'Show';event.currentTarget.setAttribute('aria-pressed',String(show));});
form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;button.disabled=true;button.textContent='Opening your training…';status.textContent='';form.setAttribute('aria-busy','true');try{const response=await fetch('/api/private?route=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.elements.email.value,password:form.elements.password.value})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Sign-in could not complete.');form.elements.password.value='';location.replace(next);}catch(error){status.textContent=error.message||'Connection failed. Please retry.';status.tabIndex=-1;status.focus();}finally{button.disabled=false;button.innerHTML='Open my training <span aria-hidden="true">↗</span>';form.removeAttribute('aria-busy');}});
fetch('/api/private?route=profile',{cache:'no-store'}).then(r=>{if(r.ok)location.replace(next);}).catch(()=>{});
